package br.com.murillo.canvasdesk.core;

import com.google.gson.*;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class PartyAndInputTest {
    @TempDir Path directory;
    @Test void onlyTheSourceAuthorIsAutomaticallyAdmitted(){var p=new MediaParties();UUID doc=UUID.randomUUID(),e=UUID.randomUUID(),author=UUID.randomUUID(),visitor=UUID.randomUUID();p.ensureActive(doc,e);p.observe(visitor,doc,author);assertFalse(p.allowed(visitor,doc,e,author));p.observe(author,doc,author);assertTrue(p.allowed(author,doc,e,author));assertFalse(p.membership(author).explicit());}
    @Test void partyFollowsBoardAndOnlyTheLastStartedVideoIsAudible(){var p=new MediaParties();UUID doc=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID(),u=UUID.randomUUID();p.join(u,doc,MediaParties.Mode.CONTINUOUS);p.activate(doc,a);assertTrue(p.allowed(u,doc,a,null));p.activate(doc,b);assertFalse(p.allowed(u,doc,a,null));assertTrue(p.allowed(u,doc,b,null));}
    @Test void onePartyAndExplicitLeaveArePreserved(){var p=new MediaParties();UUID a=UUID.randomUUID(),b=UUID.randomUUID(),u=UUID.randomUUID(),e=UUID.randomUUID();p.activate(a,e);p.join(u,a,MediaParties.Mode.PROXIMITY);p.join(u,b,MediaParties.Mode.CONTINUOUS);assertFalse(p.member(u,a));assertTrue(p.member(u,b));p.leave(u,b);p.observe(u,b,u);assertNull(p.membership(u));p.disconnect(u);p.observe(u,b,u);assertNotNull(p.membership(u));}
    @Test void guestsMustRejoinAfterDisconnectAndLegacyAuthorsAreSilent(){var p=new MediaParties();UUID d=UUID.randomUUID(),u=UUID.randomUUID(),e=UUID.randomUUID();p.activate(d,e);p.observe(u,d,null);assertFalse(p.allowed(u,d,e,null));p.join(u,d,MediaParties.Mode.CONTINUOUS);p.disconnect(u);assertFalse(p.allowed(u,d,e,null));}
    @Test void proximityAndContinuousGainsHaveDefinedBounds(){assertEquals(1,MediaParties.gain(MediaParties.Mode.PROXIMITY,4));assertEquals(.5,MediaParties.gain(MediaParties.Mode.PROXIMITY,10));assertEquals(0,MediaParties.gain(MediaParties.Mode.PROXIMITY,16));assertEquals(1,MediaParties.gain(MediaParties.Mode.CONTINUOUS,500));assertEquals(0,MediaParties.gain(MediaParties.Mode.CONTINUOUS,Double.NaN));}
    @Test void endingBoardCannotTransferConsentToAnotherDocument(){var p=new MediaParties();UUID d=UUID.randomUUID(),u=UUID.randomUUID();p.join(u,d,MediaParties.Mode.CONTINUOUS);p.end(d);assertNull(p.membership(u));}
    @Test void reliableInputIsNotDiscardedBySnapshotsOrPointerFlood()throws Exception{var q=new BrowserCommandQueue(4096);q.offer("key","down");for(int i=0;i<1000;i++){q.offer("state","s"+i);q.offer("motion","m"+i);}q.offer("key","char ç");q.offer("key","up");assertEquals("s999",q.take());assertEquals("down",q.take());assertEquals("m999",q.take());assertEquals("char ç",q.take());assertEquals("up",q.take());q.close();assertNull(q.take());}
    @Test void overflowIsExplicitAndAudioMuteHasPriority()throws Exception{var q=new BrowserCommandQueue(20);assertTrue(q.offer("key","12345678"));assertFalse(q.offer("key","abcdef"));assertTrue(q.offer("audio","mute"));assertEquals("mute",q.take());assertEquals("12345678",q.take());}
    @Test void serverSetsAuthorAndPreservesItUntilUrlActuallyChanges()throws Exception{UUID a=UUID.randomUUID(),b=UUID.randomUUID(),d,id=UUID.randomUUID();try(var store=new CanvasStore(directory)){d=store.create(a);var e=embed(id);e.addProperty("sourceAuthor",b.toString());assertTrue(store.action(d,a,edit(e,-1)).get("ok").getAsBoolean());var saved=store.element(d,id);assertEquals(a.toString(),saved.get("sourceAuthor").getAsString());var invite=new JsonObject();invite.addProperty("action","invite");invite.addProperty("player",b.toString());store.action(d,a,invite);saved.addProperty("x",80);assertTrue(store.action(d,b,edit(saved,saved.get("revision").getAsLong())).get("ok").getAsBoolean());saved=store.element(d,id);assertEquals(a.toString(),saved.get("sourceAuthor").getAsString());saved.addProperty("url","https://example.org/next.webm");assertTrue(store.action(d,b,edit(saved,saved.get("revision").getAsLong())).get("ok").getAsBoolean());assertEquals(b.toString(),store.element(d,id).get("sourceAuthor").getAsString());var undo=new JsonObject();undo.addProperty("action","undo");store.action(d,b,undo);assertEquals(a.toString(),store.element(d,id).get("sourceAuthor").getAsString());}try(var store=new CanvasStore(directory)){assertEquals(a.toString(),store.element(d,id).get("sourceAuthor").getAsString());}}
    @Test void authorshipSurvivesTransformsAndOldDocumentsDefaultUnknown(){var old=CanvasElement.fromJson(embed(UUID.randomUUID()));assertNull(old.sourceAuthor());UUID author=UUID.randomUUID();var e=old.withSourceAuthor(author).translated(256,0,UUID.randomUUID()).withRevision(9);assertEquals(author,CanvasElement.fromJson(e.toJson()).sourceAuthor());}
    private static JsonObject embed(UUID id){JsonObject e=new JsonObject();e.addProperty("id",id.toString());e.addProperty("type","EMBED");e.addProperty("url","https://example.org/video.webm");return e;}
    private static JsonObject edit(JsonObject e,long revision){JsonObject r=new JsonObject(),c=new JsonObject();r.addProperty("action","edit");r.addProperty("operationId",UUID.randomUUID().toString());c.add("id",e.get("id"));c.addProperty("expectedRevision",revision);c.add("after",e);JsonArray a=new JsonArray();a.add(c);r.add("changes",a);return r;}
}
